class Solution {
public:
    int specialPerm(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<vector<int>> memo(1 << n, vector<int>(n, -1));
        auto dp = [&](auto& self, int mask, int last) -> int {
            if (mask == (1 << n) - 1) return 1;
            if (last != -1 && memo[mask][last] != -1) return memo[mask][last];
            long long res = 0;
            for (int j = 0; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    if (last == -1 || nums[last] % nums[j] == 0 || nums[j] % nums[last] == 0) {
                        res = (res + self(self, mask | (1 << j), j)) % MOD;
                    }
                }
            }
            if (last != -1) memo[mask][last] = res;
            return res;
        };
        return dp(dp, 0, -1);
    }
};

import java.util.Arrays;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int specialPerm(int[] nums) {
        int n = nums.length;
        int[][] memo = new int[1 << n][n];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(nums, 0, -1, memo, n);
    }

    private int dfs(int[] nums, int mask, int last, int[][] memo, int n) {
        if (mask == (1 << n) - 1) return 1;
        if (last != -1 && memo[mask][last] != -1) return memo[mask][last];
        long res = 0;
        for (int j = 0; j < n; j++) {
            if ((mask & (1 << j)) == 0) {
                if (last == -1 || nums[last] % nums[j] == 0 || nums[j] % nums[last] == 0) {
                    res = (res + dfs(nums, mask | (1 << j), j, memo, n)) % MOD;
                }
            }
        }
        if (last != -1) memo[mask][last] = (int) res;
        return (int) res;
    }
}

var specialPerm = function(nums) {
    const MOD = 1000000007;
    const n = nums.length;
    const memo = Array.from({ length: 1 << n }, () => new Array(n).fill(-1));
    function dp(mask, last) {
        if (mask === (1 << n) - 1) return 1;
        if (last !== -1 && memo[mask][last] !== -1) return memo[mask][last];
        let res = 0;
        for (let j = 0; j < n; j++) {
            if (!(mask & (1 << j))) {
                if (last === -1 || nums[last] % nums[j] === 0 || nums[j] % nums[last] === 0) {
                    res = (res + dp(mask | (1 << j), j)) % MOD;
                }
            }
        }
        if (last !== -1) memo[mask][last] = res;
        return res;
    }
    return dp(0, -1);
};
